/** Every image texture Act 1 loads, as {key, path}. */
export const ACT1_IMAGE_LOADS = Object.freeze(
  Object.values(ACT1_ART).map((r) => Object.freeze({ key: r.key, path: r.path })),
);

/** Look up an art record by texture key. Returns null when unknown. */
export function getArt(key) {
  return ACT1_ART[key] || null;
}
